<template>
  <section class="trace-detail" aria-label="产品框追溯详情" :aria-busy="loading">
    <p v-if="loading" role="status">正在读取订单、工艺和原材料来源…</p>
    <div v-if="error" class="error" role="alert">{{error}} <el-button :disabled="loading" @click="load">重新读取追溯</el-button></div>
    <template v-if="detail">
      <header class="trace-heading"><div><h2>{{detail.order.plan_no}} · {{detail.box.product_name_snapshot}}</h2><p>{{detail.box.customer_part_no || '未维护客户件号'}} · {{detail.box.customer_name_snapshot || '未维护客户名称'}} · {{detail.box.product_code}}</p></div><div class="current-quantity"><span>当前数量</span><strong>{{detail.box.current_qty.toLocaleString()}} <small>件</small></strong></div></header>
      <nav aria-label="固定工艺路线"><ol class="route"><li v-for="step in detail.route.steps" :key="step.code" :aria-current="step.code === detail.box.current_process_code ? 'step' : undefined" :class="{current:step.code===detail.box.current_process_code}"><b>{{step.name || step.code}}</b><span>{{step.code}}{{step.code === detail.box.current_process_code ? ' · 当前' : ''}}</span></li></ol></nav>
      <p class="muted">{{detail.route.route_code}} · 路线版本 v{{detail.route.revision}}<span v-if="detail.latest_event"> · 最近业务事件：{{eventName(detail.latest_event.event_type)}}，{{time(detail.latest_event.occurred_at)}}</span></p>
      <div class="split-action"><el-button v-if="detail.split?.allowed_actions.length" type="primary" @click="splitVisible=true">拆分产品框</el-button><p v-else-if="detail.split?.reason" class="muted">{{detail.split.reason}}</p></div>
      <section v-if="detail.relations_total || detail.exceptions_total || detail.conversions_total" aria-label="关联记录"><h3>关联记录</h3><p v-if="!detail.relations_total && !detail.exceptions_total && !detail.conversions_total" class="muted">暂无拆框、规格异常或转换记录。</p><div v-for="row in detail.relations" :key="`r${row.id}`" class="related-record"><div class="related-row"><span>{{eventName(row.relation_type)}} · {{row.quantity}} 件 · PP-{{String(row.source_order_id).padStart(6,'0')}} → PP-{{String(row.target_order_id).padStart(6,'0')}}</span><el-button link @click="$emit('navigate', row.parent_box_id === boxId ? row.child_box_id : row.parent_box_id)">{{row.parent_box_id === boxId ? '查看子框' : '查看父框'}}</el-button></div><p>父框当前 {{row.parent_current_qty ?? '未记录'}} 件 · 子框当前 {{row.child_current_qty ?? '未记录'}} 件 · 拆出来源用途：订单 {{row.order_qty}} 件 / 备货 {{row.stock_qty}} 件</p><details><summary>查看来源快照与标签编号</summary><p>拆分前 {{row.source_snapshot.current_qty}} 件 · {{row.source_snapshot.product_name}} · {{row.source_snapshot.process_code}}</p><code>{{row.parent_box_no}} → {{row.child_box_no}}</code></details></div><p v-for="row in detail.exceptions" :key="`e${row.id}`">规格异常 · {{row.status}} · {{row.resolution || '等待处理'}} · {{row.remark || '无备注'}}</p><p v-for="row in detail.conversions" :key="`c${row.id}`">{{row.source_product_code}} → {{row.target_product_code}} · {{row.confirmation_status}} · {{row.actual_qty ?? '待确认'}} 件</p><el-button v-if="hasMoreRelated" :loading="relatedLoading" @click="moreRelated">读取更多关联记录</el-button><p v-if="relatedError" class="error" role="alert">{{relatedError}}</p></section>
      <section aria-label="工艺数量记录"><h3>工艺数量记录</h3><el-table :data="detail.quantities" row-key="id" empty-text="尚未登记工艺数量"><el-table-column prop="process_code" label="工艺" min-width="110"/><el-table-column prop="machine_no" label="机台" min-width="135"/><el-table-column label="入量快照" width="115" align="right"><template #default="{row}">{{row.input_qty}} 件</template></el-table-column><el-table-column label="当前保存值" width="125" align="right"><template #default="{row}"><b>{{row.current_qty}} 件</b></template></el-table-column><el-table-column label="操作人" min-width="140"><template #default="{row}">{{row.operator_name || `账号 ${row.updated_by}`}}</template></el-table-column><el-table-column label="更新时间" min-width="170"><template #default="{row}">{{time(row.updated_at)}}</template></el-table-column></el-table></section>
      <section aria-label="原材料来源"><h3>原材料来源</h3><p v-if="detail.missing_material_source" class="muted">尚未记录材料来源，无法据此确认原材料批次。</p><p v-if="detail.material_lineage_incomplete" class="error" role="alert">材料来源链存在循环或超出读取深度，请核对历史台账。</p><el-table v-if="detail.materials.length" :data="detail.materials" row-key="id"><el-table-column label="物料 / 牌号" min-width="180"><template #default="{row}"><strong>{{row.material_name || '历史物料未维护'}}</strong><span class="subline">{{row.grade || '未维护牌号'}}</span></template></el-table-column><el-table-column prop="batch_no" label="业务批次" min-width="180"/><el-table-column label="来源层级" width="110"><template #default="{row}">{{row.depth === 0 ? '直接用料' : `上溯 ${row.depth} 层`}}</template></el-table-column><el-table-column label="规格" min-width="140"><template #default="{row}">{{row.thickness ?? '未维护'}} × {{row.width ?? '未维护'}} mm</template></el-table-column><el-table-column label="台账余重" width="110" align="right"><template #default="{row}">{{row.current_weight ?? '未记录'}} kg</template></el-table-column></el-table></section>
      <section aria-label="工艺事件历史"><h3>工艺事件历史 <small>{{eventRows.length}} / {{detail.events.total}}</small></h3><p v-if="eventError" class="error" role="alert">{{eventError}}</p><el-table :data="eventRows" row-key="id" empty-text="尚无事件"><el-table-column label="时间" min-width="165"><template #default="{row}">{{time(row.occurred_at)}}</template></el-table-column><el-table-column label="事件 / 工艺" min-width="150"><template #default="{row}"><b>{{eventName(row.event_type)}}</b><span class="subline">{{row.process_code || '订单操作'}}</span></template></el-table-column><el-table-column label="机台 / 操作人" min-width="180"><template #default="{row}">{{row.machine_no || '—'}}<span class="subline">{{row.operator_name || `账号 ${row.operator_id}`}}</span></template></el-table-column><el-table-column label="数量变化" min-width="120" align="right"><template #default="{row}">{{row.before_qty}} → {{row.after_qty}}</template></el-table-column><el-table-column label="依据" min-width="200"><template #default="{row}"><span v-if="row.remark">{{row.remark}}</span><span v-else-if="row.event_type==='process_start'">{{row.before_snapshot.process_code}} 出量 {{row.before_snapshot.output_qty}} → {{row.after_snapshot.process_code}} 入量 {{row.after_snapshot.input_qty}}</span><details v-else-if="Object.keys(row.after_snapshot).length"><summary>查看记录快照</summary><pre>{{JSON.stringify(row.after_snapshot,null,2)}}</pre></details><span v-else>—</span></template></el-table-column></el-table><el-button v-if="cursor || eventError" class="load-more" :loading="eventsLoading" @click="moreEvents">读取更早事件</el-button></section>
      <details class="identity"><summary>框号与追溯标识（辅助）</summary><p>{{detail.box.box_no}}</p><code>{{detail.box.qr_payload}}</code></details>
    </template>
    <SplitBoxDialog v-if="splitVisible" :parent-id="boxId" @cancel="splitVisible=false" @completed="afterSplit"/>
  </section>
</template>

<script setup lang="ts">
import {computed, ref, watch} from 'vue'
import {productTraceApi as api} from '@/api/productTrace'
import type {QrId} from '@/types/productBox'
import type {BoxTrace, FlowEvent} from '@/types/productTrace'
import {qrError} from '@/views/product-box-qr/messages'
import SplitBoxDialog from './SplitBoxDialog.vue'
import {ElMessage} from 'element-plus'
const props=defineProps<{boxId: QrId}>()
defineEmits<{navigate:[boxId:QrId]}>()
const detail=ref<BoxTrace|null>(null), loading=ref(false), error=ref(''), eventRows=ref<FlowEvent[]>([]), cursor=ref<QrId|null>(null)
const eventsLoading=ref(false), eventError=ref(''), relatedLoading=ref(false), relatedError=ref('')
const splitVisible=ref(false)
async function afterSplit(){splitVisible.value=false;ElMessage.success('拆分已保存，父子余量和来源已更新');await load()}
let generation=0
const time=(value:string)=>new Date(value).toLocaleString('zh-CN',{hour12:false})
const eventName=(value:string)=>({bind:'绑定',scan:'扫码查询',qty_save:'保存数量',process_start:'进入工艺',process_complete:'工艺完成',quantity_correction:'主管更正',metadata_edit:'标签资料修改',allocation:'用途分配',split:'拆框',cross_order_split:'跨单拆框',conversion:'产品转换',exception:'规格异常',resume:'恢复'} as Record<string,string>)[value]||value
const hasMoreRelated=computed(()=>!!detail.value&&(['quantities','relations','exceptions','conversions'] as const).some(key=>detail.value![key].length<detail.value![`${key}_total`]))
async function load(){const request=++generation;loading.value=true;error.value='';detail.value=null;eventRows.value=[];cursor.value=null;eventError.value='';relatedError.value='';try{const result=await api.trace(props.boxId);if(request!==generation)return;detail.value=result;eventRows.value=result.events.items;cursor.value=result.events.next_cursor}catch(reason){if(request===generation)error.value=qrError(reason)}finally{if(request===generation)loading.value=false}}
async function moreEvents(){if(eventsLoading.value||!cursor.value)return;const request=generation;eventsLoading.value=true;eventError.value='';try{const result=await api.events(props.boxId,{before_id:cursor.value});if(request!==generation)return;eventRows.value.push(...result.items);cursor.value=result.next_cursor;if(detail.value)detail.value.events.total=result.total}catch(reason){if(request===generation)eventError.value=qrError(reason)}finally{eventsLoading.value=false}}
async function moreRelated(){if(relatedLoading.value||!detail.value)return;const request=generation;relatedLoading.value=true;relatedError.value='';try{const result=await api.trace(props.boxId,{page:detail.value.page+1});if(request!==generation||!detail.value)return;for(const key of ['quantities','relations','exceptions','conversions'] as const){(detail.value[key] as unknown[]).push(...result[key])}detail.value.page=result.page}catch(reason){if(request===generation)relatedError.value=qrError(reason)}finally{relatedLoading.value=false}}
watch(()=>props.boxId,()=>{splitVisible.value=false;load()},{immediate:true})
</script>

<style scoped>
.trace-detail{color:var(--zephyr-ink);font-size:13px}.trace-heading{display:flex;justify-content:space-between;gap:24px;margin-bottom:20px}h2{font-size:18px;margin:0 0 8px}h3{font-size:14px;margin:0 0 12px}h3 small{font-size:12px;color:var(--zephyr-muted);font-weight:400}p{font-size:12px;line-height:1.7;margin:4px 0}.muted,.subline{color:var(--zephyr-muted)}.current-quantity{display:flex;flex-direction:column;gap:6px;white-space:nowrap}.current-quantity span{font-size:12px;color:var(--zephyr-muted)}.current-quantity strong{font-size:30px}.current-quantity small{font-size:12px;font-weight:400}.route{display:flex;list-style:none;padding:0;margin:0 0 12px;gap:8px;flex-wrap:wrap}.route li{display:flex;flex-direction:column;gap:4px;padding:8px 16px;border-bottom:2px solid var(--zephyr-border);color:var(--zephyr-muted)}.route .current{color:var(--zephyr-primary);background:var(--zephyr-primary-soft);border-color:var(--zephyr-primary)}.route li span{font-size:11px}.trace-detail>section{padding-top:24px;margin-top:20px;border-top:1px solid var(--zephyr-border-soft)}.subline{display:block;font-size:11px;margin-top:4px}.trace-detail :deep(.el-table){font-variant-numeric:tabular-nums}.load-more{margin-top:12px}.related-record+.related-record{margin-top:16px}.related-row{display:flex;align-items:center;gap:12px}.error{color:var(--zephyr-danger);font-size:12px;margin-bottom:12px}.identity{font-size:11px;color:var(--zephyr-muted);margin-top:24px}.identity summary,details summary{cursor:pointer;width:fit-content}summary:focus-visible{outline:2px solid var(--zephyr-primary);outline-offset:3px}code,pre{font:11px var(--zephyr-font-mono);overflow-wrap:anywhere;white-space:pre-wrap}pre{max-width:400px}.current-quantity{font-variant-numeric:tabular-nums}@media(max-width:600px){.trace-heading{flex-direction:column;gap:12px}.route li{padding:8px}.related-row{flex-wrap:wrap}}
</style>
